	title 'LineEditProc'************************************************************************ LineEdit Control Def Proc*** Copyright (C)* Apple Computer, Inc.  1986-1989* All Rights Reserved** 24 Sep 88	Steven Glass** Coding begin from version of the editLine custom control* in the dialog manager.** 01 Dec 88	Steven Glass** The drawing routine now checks to see if the control is visible.** 06 Feb 89	Harry Yee** In do_draw routine, we now check if SpecialRect returns an error, if it does then* I assume that the error is a dispatcher error, i.e. function not found as would be,* in the case of pre-3.2 system disks, I then clean up the stack and call EraseRect and* FrameRect instead. ** 15 Feb 89	Harry Yee** We now "include" LineEditEquates.asm. This holds the equates for line* edit's direct page variables which we now need. In Do_Track when* the control is being made active for the first time we now zero the ClickTime* variable on direct page. This variable holds the last time that a mouse down* occurred in a line edit control (any line edit control). Double/Triple clicks* when clicking between several line edit controls now works. * BRC #38970.** 10 Mar 89	Steven Glass** Changed names associated with active controls to target controls.** 15 Mar 89	Steven Glass** Don't make control target if it is invisible.** 24 Mar 89	Harry Yee** Fixed problem in do_ChangeTarget, do_TakeTab, and do_TakeEvent. We were not checking * whether Target was visible or not before trying to deactivate it. Fixed.** The lineEdit defprocs no longer call StartDrawing or SetOrigin(0,0). Its up to the* program calling the defprocs to set the origin correctly (in this case TaskMaster).** 28 Mar 89	Steven Glass** Added support for the ctlWinStateChagne message.  Invalrect is called* in response to this message so that the control will be redrawn.*** 12 Apr 89	Steven Glass** Changed do_TakeEvent to reject events if control is inactive.** 19 apr 89	Steven Glass** Changed the init routine.  Could not handle initial value being* a handle.** 18...19-Sep-90	Dave Lyons** Changed how do_track constructs an event record to pass to LEClick.* We weren't getting real Modifiers before, so we couldn't shift-click* to extend the selection.  Now I call GetNextEvent with a 0 event mask,* so we get real modifiers.  (This actually saves code [for the RAM* toolset] because the old scheme was to call TickCount and ReadMouse* and copy the results into the event record.)** Also removed all.macros dependency and changed rString to rPString.** 11-Mar-91	Dave Lyons** Add a field to the template to control what the Password character is.* Put all.macros back.** 22-Aug-91	Dave Lyons** Changed do_TakeEvent to branch to @HandleTab even if the Command key* is down, so that MakeNextCtlTarget will get called with Command* down to cycle through the controls backwards.** 5-Sep-91	Dave Lyons** Creating a Line Edit control with 9 parameters & the Password char* field = $0000 gives you the default password character (regardless* of bit 15 of the maxLen field).************************************************************************* 23-Mar-92	Dave Lyons for 6.1** Add optional parameter #10 for allowing only certain characters* into the field.  (The control record is now the standard one plus* one word for keyMask.)** 24-Mar-92	Dave Lyons** If the password character field in the template is $FFFF, then this* actually isn't a password field.***********************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include ':::ControlMgr:CtlCustomEqus.asm'	include 'e16.quickdraw'	include 'e16.font'	include 'e16.event'	include 'e16.resources'	include 'e16.lineedit'	include 'LineEditEquates.asm'	MACRO	PushZPtr &A	pea  $0000	tdc	clc	adc  #&A	pha	MENDTrue	equ $FFFFFalse	equ 0LineEditPartCode 	equ $80y1	equ 0x1	equ 2y2	equ 4x2	equ 6TabKey	equ 9ReturnKey	equ 13	MACRO&lab	link &SizeInput,&SizeLocals	lclc &SL&SL	setc &DEFAULT(&SizeLocals,'0')input	equ &SL+3output	equ input+&SizeInput&lab	tsc	sec	sbc #&SL	tcs	phd	inc a	tcd	MEND	MACRO&lab	unlink&lab	pld	tay	lda input-1,s	sta output-1,s	lda input-2,s	sta output-2,s	tsc	clc	adc #output-3	tcs	tya	cmp #1	MEND	print pop	title 'Proc Entry';___________________________________________________________________________;;       LineEditProc;;       input: message:WORD - desired operation;              param:LONG - depends on operation;              ctlHandle:LONG - handle	to control;;      output: RetValue:LONG - depends on operation;____________________________________________________________________________LineEditProc	PROC	dsect 0ctlPtr	longRect	block 8FontInfo	block 8FontHeight	wordDestRect	block 8SizeLocals	DSectSize	link 10,SizeLocals	DSect inputctlHandle	longCtlParam	longCtlMessage	WORDRetValue	equ output;; Zeroes out RetValue;	stz <RetValue	stz <RetValue+2;; Check to see which message.  If it is	the RecSize msg then; skip this part which sets port and origin since pointers; in control handle	are not yet valid.;	lda <CtlMessage	cmp #RecSize	beq SkipThisShit;; Derefence Control	Handle;	jsr DerefCtlHandle;; Get a copy of the	enclosing rect;	ldy #NewCtlRecord.ctlRect	lda [<ctlPtr],y	sta Rect	iny	iny	lda [<ctlPtr],y	sta Rect+2	iny	iny	lda [<ctlPtr],y	sta Rect+4	iny	iny	lda [<ctlPtr],y	sta Rect+6SkipThisShit;; Dispatch;	lda <CtlMessage	cmp #ctlWinStateChange+1	bcs NotHandled	asl a	tax	jsr (CmdTable,x)NotHandled	unlink	rtl	; quit procedureCmdTable	DC.W Do_Draw		0 DRAW	DC.W Do_Nothing		1 compute DragRect	DC.W do_test		2 common hit test	DC.W Do_Init		3 Init routine	DC.W Do_Dispose		4 dispose routine	DC.W Do_Nothing		5 new value	DC.W Do_Nothing		6 thumb constraints	DC.W Do_Track		7 drag indicator	DC.W Do_Nothing		8 auto action proc	DC.W Do_Draw		9 new value	DC.W Do_Nothing		10 set min/max	DC.W Do_Move		11 move control	DC.W Do_RecordSize		12 record size	dc.W Do_TakeEvent		13 take key or menu event	dc.w Do_TargetChange	14 Activity changed	dc.w do_nothing		15 Change Bounds	dc.w do_nothing		16 Window changed size	dc.w do_TakeTab		17 handle a tab	dc.w do_nothing		18 multi part event	dc.w do_inval		19 Winstate changeDo_Nothing	rts	title 'Do_Draw'*****************************************************************Do_Draw** Draws the LineEdit item in response to the control manager* request.** This draw routine, frames and erases the bounding rectangle* and then calls LEUpdate.*** Inputs:*	param     PartCodeToDraw*	param+2   Hilite State** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	jsr CheckVis	beq @Continue	rts@continue;-----------------------------------------------------------;; Guarentee the text color;;-----------------------------------------------------------	pea $0000	_SetForeColor	pea $FFFF	_SetBackColor	lda ctlparam+2	beq @WeAreTarget;-----------------------------------------------------------;; The control is "dim".  Do we think we are target?; If yes, we must tell lineedit to untarget.;;-----------------------------------------------------------@WeAreNotTarget	jsr DeActivate	bra @ok;-----------------------------------------------------------;; The control is not dim.  Do we think we are target?  If; yes, we must tell line edit to activate.;;-----------------------------------------------------------@WeAreTarget	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #FctlTarget	beq @WeAreNotTarget	jsr Activate@OK;; Draw EditLine enclosing rect;	pushzptr <Rect	PushWord #0	PushWord #$FFFF	_SpecialRect	bcc SpecialRectOK	tsc	; Fix stack from SpecialRect call	clc	adc #8	tcs		pushzptr <Rect	; Fill area we're going to frame with the background 		_EraseRect	; color		_PenNormal			pha	; width of pen depends on the mode we're in	_GetMasterSCB	pla	and #$0080	beq In320		pea 2	; pen width is 2 in 640 mode	bra PushHeight	In320	pea 1	; pen width is 1 in 320 modePushHeight	pea 1	; pen height is 1	_SetPenSize		pea 0	; set the pen pattern to be solid black	_SetSolidPenPat		pushzptr <Rect	; frame the edit line item		_FrameRect	;; ReDraws the Line by calling LineEdit;SpecialRectOK	jsr PushCtlData	_LEUpdate	rts	title 'Do_Test'*****************************************************************Do_Test** Returns the part code for an indicator so that the defProc* can do its own custom dragging.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #LineEditPartCode	sta <RetValue	rts	title 'Do_Test'*****************************************************************Do_TakeTab** Selects the contents of the text.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	jsr CheckVis	beq @Continue	rts@Continue	pushword #0		; select all the default text	pushword #32767	jsr PushCtlData	_LESetSelect	rts	title 'Do_Track'*****************************************************************do_track** This is the routine that is called when the mouse goes down* in the control.** The control manager calls this routine because, the * test routine returned a part code of $80.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;-----------------------------------------------------------;; Look at the part code.  If it is zero, the whole control; wants to be dragged.;;-----------------------------------------------------------	lda <CtlParam	bne @GoOn	rts@GoOn;-----------------------------------------------------------;; Start by making this control Target.  To do so, we have; to see if we are already Target.;; If we are, then all is well, otherwise, we just have to; deactivate whoever and force a redraw.;;-----------------------------------------------------------	ldy #NewCtlRecord.CtlMoreFlags	lda [CtlPtr],y	and #FCtlTarget	bne @AlreadyTarget;; --- This line edit control is being made Target for the first time ---------------;	pea 0	; space for result	pea 0		pea 0	; System toolset	pea LETSNum	; Line Edit toolset number	_GetWAP	plx	pla	lda #0	; just in case its not on zero page	sta >ClickTime,x	; reset the last time mouse down happened to	sta >ClickTime+2,x	; zero, so double/triple clicks work correctly	pei CtlHandle+2	pei CtlHandle	_MakeThisCtlTarget@AlreadyTarget;-----------------------------------------------------------;; Now that the control is activated, we have to handle; the mouse down.  The tricky part here is that; we don't have the real event record.  What will; we do?;; We build a fake record on the stack.;;-----------------------------------------------------------	DefineStackAnEventWhat   	word	EQU   $00 ; Word - WmTaskRec -  AnEventMessage   	LONG	EQU   $02 ; Long - WmTaskRec -  AnEventWhen   	LONG	EQU   $06 ; Long - WmTaskRec -  AnEventWhere   	LONG	EQU   $0A ; Point - WmTaskRec -  AnEventModifiers   	WORD	EQU   $0E ; Word - WmTaskRec -  	lda #0	pha	; mods	pha	; where	pha	; where	pha	; when	pha	; when	pha	; message	pha	; message	pha	; what*** replaced the following section 18-Sep-90 DAL (see GetNextEvent below)***	pha***	pha***	pha***	_ReadMouse***	pla***	pla***	plx***	sta AnEventWhere,s***	txa***	sta AnEventWhere+2,s******	lda #1***	sta AnEventWhat,s******	pha	;replaced 18-Sep-90 DAL (see GetNextEvent below)***	pha***	_TickCount***	pla***	plx***	sta AnEventWhen,s***	txa***	sta AnEventWhen+2,s******	lda #%0000000001000000***	sta AnEventModifiers,s******	tsc***	inc a***	pea $0000***	pha*** New scheme 18-Sep-90 DAL lets us handle shift-clicking	tsc	inc a	ldx #0	phx	pha	;pushed event record ptr for LEClick	phx	;result space for GetNextEvent	phx	;ZERO event mask for GetNextEvent	phx	;event rec ptr for GetNextEvent	pha	_GetNextEvent	pla	;throw away the flag	lda #1	;mouseDown event	sta AnEventWhat+4,s	;+4 because EventRec ptr for LEClick is pushed*** end of 18-Sep-90 DAL change	jsr PushCtlData	_LEClick	pla	; what	pla	; message	pla	; message	pla	; when	pla	; when	pla	; where	pla	; where	pla	; modifiers	lda #True	; tell control manage that we handled the drag.	sta <RetValue	lda #LineEditPartCode	sta <RetValue+2	rts	title 'Do_Init'*****************************************************************Do_Init** This is the hard working routine that takes the input from* the input template and builds the appropriate LineEdit* record.*** Inputs:*	ctlParam   pointer to template*	ctlHandle  The control handle*	ctlPtr     The control pointer*	ctlRect    control's rectangle** Outputs:*	none** External Refs:	import LoadResource	import ReleaseResource** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 19 Apr 89	Steven Glass** Could not pass the initial value by handle.  Was not setting* direct page up correctly.*****************************************************************;-----------------------------------------------------------;; This is a line edit control so it can be Target and it; can take key strokes.  So I force these bits on.;;-----------------------------------------------------------	ldy #NewCtlRecord.CtlMoreFlags	lda #FCtlCanBeTarget+FCtlWantEvents	ora [CtlPtr],y	sta [CtlPtr],y;-----------------------------------------------------------;; LineEdit expects the current port to be the port; we will do the editing in.;;-----------------------------------------------------------	pha	; save the current	pha	_GetPort	ldy #NewCtlRecord.ctlOwner+2	lda [ctlPtr],y	pha	dey	dey	lda [ctlPtr],y	pha	_SetPort;; Calculate the view rectangle;	pushzptr Rect	pushword #2	pushword #1	_InsetRect;; Calculate the font height;	pushzptr FontInfo	_GetFontInfo	lda <FontInfo	; ascent	clc	adc <FontInfo+2	; descent	adc <FontInfo+6	; leading	sta <FontHeight;; Calculate how much the destRect must be inseted;	lda <Rect+0	sta <DestRect+0	lda <Rect+2	sta <DestRect+2	lda <Rect+4	sta <DestRect+4	lda <Rect+6	sta <DestRect+6	lda <Rect+y2	; inset = (viewRect.y2 - viewRect.y1	sec	;         - FontHeight)/2	sbc <Rect+y1	sbc <FontHeight	lsr a	tax	pushzptr DestRect	pushword #4	; horizontal inset = 4	phx	; vertical inset computed to center text	_InsetRect;; Create the LineEdit Record;	pha	; space for Line Edit Handle	pha	pushzptr <DestRect	pushzptr <Rect	ldy #LineEditTemplate.MaxLen	; max length	lda [<ctlParam],y	pha	_LENew	jsr DerefCtlHandle	ldy #NewCtlRecord.ctlData	pla	sta [<ctlPtr],y	iny	iny	pla	sta [<ctlPtr],y;; Test if TextPtr is Nil or not;	ldy #LineEditTemplate.IVRef	lda [<ctlParam],y	bne DefaultText	iny	iny	lda [<ctlParam],y	bne DefaultText	brl FinishUp;; Set the edit text	to the string passed as parameter;DefaultText;; Copy the reference to direct page in rect.;	ldy #LineEditTemplate.IVRef	lda [ctlParam],y	sta rect	iny	iny	lda [ctlParam],y	sta rect+2;; look at the ref descriptor;	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #IVVerbMask	tax	; put copy here	beq @IsPtr	cmp #IVIsHandle	beq @ISHandle;; load the resource;@IsResource	pha	pha	PushWord #rPString	;was rString 19-Sep-90 DAL	pei rect+2	pei rect	_CMLoadResource	pla	sta Rect	pla	sta Rect+2	jsr DerefCtlHandle;; deref the handle;@IsHandle	lda [Rect]	tax	ldy #2	lda [Rect],y	sta Rect+2	stx Rect;; bump the pointer by 1 and call set text.;@IsPtr	lda Rect+2	ldx Rect	inx	bne @NoCarry	inc a@NoCarry	pha	phx	lda [Rect]	and #$00FF	pha	jsr PushCtlData	_LESetText	jsr DerefCtlHandle	pushword #0		; select all the default text	pushword #32767	jsr PushCtlData	_LESetSelect	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #IVVerbMask	cmp #IVIsResource	bne FinishUp	PushWord #rPString		;was rString 19-Sep-90 DAL	ldy #LineEditTemplate.IVRef+2	lda [<ctlParam],y	pha	dey	dey	lda [<ctlParam],y	pha	_CMReleaseResourceFinishUp*** Check for the Password character field	lda [<ctlParam]	;check paramater count	cmp #9	bcc @noPWChar	ldy #LineEditTemplate.PasswordChar	lda [<ctlParam],y	bmi @noPWChar	;added 24-Mar-92 DAL	bne @havePWChar	lda #defaultPWChar	;$0000 --> default password character!@havePWChar	pha	jsr PushCtlData	phd	tsc	tcd	ldy #2	lda [3],y	pha	lda [3]	sta 3	pla	sta 5	;derefed LE Record to <3	lda 7	;get Password Character back	ldy #lePWChar	sta [3],y	pld	plx	plx	;throw away long	plx	;throw away password character@noPWChar*** added 23-Mar-92 DAL;; Copy keyMask parameter from template to record;	ldx #1	;anticipate keyMask = $0001	lda [<ctlParam]	cmp #10	bcc @defaultMask	ldy #LineEditTemplate.keyMask	lda [<ctlParam],y	tax@defaultMask	txa	ldy #NewCtlRecord.ctlOptionalData	sta [<ctlPtr],y*** end 23-Mar-92;-----------------------------------------------------------;; Make this the Target control (unless the invis bit is set).;;-----------------------------------------------------------	ldy #NewCtlRecord.CtlFlag	lda [<ctlPtr],y	and #ctlInvis	bne @DontMakeTarget	_HidePen	pei <CtlHandle+2	; make this the Target control	pei <CtlHandle	_MakeThisCtlTarget	_ShowPen@DontMakeTarget	_SetPort	Restore the current	port.	rts	title 'Do_Move'*****************************************************************Do_Move** This is the routine that adjusts the leRecord after the control* has been moved.*** Inputs:*	ctlParam   delta Y and deltaX*	ctlHandle  The control handle*	ctlPtr     The control pointer*	ctlRect    control's new rectangle** Outputs:*	none** External Refs:	import LoadResource	import ReleaseResource** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;; Save the port and set the port to the window.;	pha	; save the current	pha	_GetPort	ldy #NewCtlRecord.ctlOwner+2	lda [ctlPtr],y	pha	dey	dey	lda [ctlPtr],y	pha	_SetPort;; Calculate the view rectangle;	pushzptr Rect	pushword #2	pushword #1	_InsetRect;; Calculate the font height;	pushzptr FontInfo	_GetFontInfo	lda <FontInfo	; ascent	clc	adc <FontInfo+2	; descent	adc <FontInfo+6	; leading	sta <FontHeight;; Calculate how much the destRect must be inseted;	lda <Rect+0	sta <DestRect+0	lda <Rect+2	sta <DestRect+2	lda <Rect+4	sta <DestRect+4	lda <Rect+6	sta <DestRect+6	lda <Rect+y2	; inset = (viewRect.y2 - viewRect.y1	sec	;         - FontHeight)/2	sbc <Rect+y1	sbc <FontHeight	lsr a	tax	pushzptr DestRect	pushword #4	; horizontal inset = 4	phx	; vertical inset computed to center text	_InsetRectOldLERec	equ FontInfo;; Get the old LE Record handle and deref it;	ldy #NewCtlRecord.ctlData+2	lda [<ctlPtr],y	sta OldLERec+2	dey	dey	lda [<ctlPtr],y	sta OldLERec	lda [OldLERec]	tax	ldy #2	lda [OldLERec],y	sta OldLERec+2	stx OldLERec;; Copy the DestRect into the LE record;	ldy #oleDestRect	ldx #0@Loop1	lda DestRect,x	sta [OldLERec],y	iny	iny	inx	inx	cpx #8	bcc @Loop1;; Copy the ViewRect into the LERecord;	ldy #oleViewRect	ldx #0@Loop2	lda Rect,x	sta [OldLERec],y	iny	iny	inx	inx	cpx #8	bcc @Loop2	_SetPort	rts	title 'Do_Dispose'*****************************************************************Do_Dispose		; ** Disposes of the LE record when the control record is * being killed.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	jsr PushCtlData	_LEDispose	rts	title 'Do_TargetChange'*****************************************************************Do_TargetChange** This is the little routine is called when the ChangeTarget* message is called.*** Inputs:*	ctlHandle   Control's handle*	ctlPtr      (Handle derefed)*	ctlParam    not used** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	jsr CheckVis	beq @Continue	rts@Continue	ldy #NewCtlRecord.ctlMoreFlags	lda [ctlPtr],y	and #FCtlTarget	beq @Deactivate	jsr Activate	bra @Fini@Deactivate	jsr Deactivate@Fini	rtsActivate	jsr PushCtlData	_LEActivate	rtsDeactivate	jsr PushCtlData	_LEDeactivate	rts	title 'Do_TakeEvent'*****************************************************************Do_TakeEvent** This is the little routine that handles key strokes, menu* events and idle events.*** Inputs:*	ctlHandle   Control's handle*	ctlPtr      (Handle derefed)*	ctlParam    pointer to task record** Outputs:*	retValue is true indicating we took the event** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 06 Jan 88	Steven Glass** Added code to look at the modifiers.  If apple key is down,* we ignore the key stroke unless it is an arrow key.** 12 Apr 89	Steven Glass** Check hilite flag and reject event if ctl is inactive.*****************************************************************	jsr CheckVis	beq @Continue	rts@continue; Added 12 Apr 89 SEG	ldy #NewCtlRecord.ctlFlag	Look at the flag and hilite	lda [<ctlPtr],y		bytes.  If hilite is FF	and #$FF00		we are inactive and should	cmp #$FF00		ignore the event.	beq @RejectEvent; End Addition	lda [ctlParam]	bne @NotNull	jsr PushCtlData	_LEIdle	lda #True	brl @Fini@NotNull	cmp #keyDownEvt	beq @IsKey	cmp #AutoKeyEvt	beq @IsKey@RejectEvent	lda #False	bra @Fini@IsKey;; If the apple key is down only accept the arrow keys, otherwise; reject the key.;*** added 22-Aug-91 DAL -- accept Command-tab as Tab!	ldy #oMessage	lda [ctlParam],y	cmp #TabKey	beq @HandleTab*** end 22-Aug-91 DAL	ldy #oModifiers	lda [ctlParam],y	and #appleKey	beq @NotModified	ldy #oMessage	lda [ctlParam],y	cmp #8	; left arrow	beq @NotModified	cmp #$15	; right arrow	bne @RejectEvent@NotModified*** added 23-Mar-92 DAL -- filter out unwanted keys	pha	;space for LEClassifyKey	pei <ctlParam+2	pei <ctlParam;	_LEClassifyKey	ldx #$2514	jsl $e10000	pla	ldy #NewCtlRecord.ctlOptionalData	and [<ctlPtr],y	beq @rejectEvent*** end 23-Mar-92	ldy #oMessage	lda [ctlParam],y	cmp #ReturnKey	beq @RejectEvent	pha	ldy #oModifiers	lda [ctlParam],y	pha	jsr PushCtlData	_LEKey@TakeIt	lda #True@Fini	sta <RetValue	rts;-----------------------------------------------------------;; We have a tab, so we try to make the next control Target.; If we are the only control, we end up ignoring the tab.; If we are not the only control, we send the ; ctlHandleTab message to the newly Target control;;-----------------------------------------------------------@HandleTab	pha	; make the next one Target	pha	_MakeNextCtlTarget	pla	plx	cmp ctlHandle	; is it us?	bne @NotSame	; no	cpx ctlHandle+2	beq @TakeIt	; yes@NotSame		; no	pha	; Call the new one.	pha	phx	pha	PushWord #ctlHandleTab	PushLong #0	_CallCtlDefProc	pla	pla	bra @TakeIt	title 'Do_RecordSize'*****************************************************************Do_RecordSize** Returns the size of the control record that we need.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************;	lda #SuperCtlSize*** 23-Mar-92 DAL -- keyMask field is now on the end	lda #SuperCtlSize+2*** end 23-Mar-92	sta <RetValue	rts	title 'Do_Inval'*****************************************************************Do_Inval** Invalidates the control record in response to a window state* change message.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	PushZPtr Rect	_InvalRect	rts	title 'Utilities'************************************************************************ Various Utilities***********************************************************************CheckVis	ldy #NewCtlRecord.ctlFlag	; make sure we are visible	lda [ctlPtr],y		; before we draw.	and #ctlInVis	rtsPushCtlData	plx	ldy #NewCtlRecord.ctlData+2	lda [<ctlPtr],y	pha	dey	dey	lda [<ctlPtr],y	pha	phx	rtsDerefCtlHandle	lda [<ctlHandle]	sta <ctlPtr	ldy #2	lda [<ctlHandle],y	sta <ctlPtr+2	rts	ENDP*****************************************************************GetLEDefProc	PROC Export** Returns the address of the LineEdit control def-proc.*** Inputs:*	space for pointer** Outputs:*	Pointer to DefProc** External Refs:	import LineEditProc** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackRTL1	block 3RTL2	block 3ThePointer	LONG	lda #LineEditProc	sta ThePointer,s	lda #^LineEditProc	sta ThePointer+2,s	lda #0	clc	rtl	ENDP	END